using System.Text;
using Tralys.Ecs.Generators.CodeGen;
using Tralys.Ecs.Generators.Indexes;

namespace Tralys.Ecs.Generators.Metadata;

static class ModuleEmitter
{
    const string Unsafe = "global::System.Runtime.CompilerServices.Unsafe";
    public const string Hidden =
        "[global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]";

    public static string Header =>
        "// <auto-generated/>\n#nullable enable\n#pragma warning disable\n";

    public static string HintName(string displayName)
    {
        var text = new StringBuilder();
        foreach (var c in displayName)
            text.Append(char.IsLetterOrDigit(c) || c == '.' ? c : '_');
        return text.ToString();
    }

    public static string Type(TypeModel model)
    {
        var writer = new CodeWriter();
        writer.Line(Header);
        if (model.Namespace.Length > 0)
            writer.Line($"namespace {model.Namespace};");
        writer.Line();

        var scopes = new List<CodeWriter.Scope>();
        foreach (var container in model.Containers.Items)
            scopes.Add(writer.Block($"partial {container.Keyword} {container.Name}"));

        using (
            writer.Block(
                $"{Symbols.Partial(model.Keyword)} {model.DeclarationName} : {Interfaces(model)}"
            )
        )
        {
            if (model.Kind != DeclKind.Tag)
            {
                Fields(writer, model);
                writer.Line();
                Offsets(
                    writer,
                    model.FullName,
                    "public static",
                    "__EcsEntityRefs",
                    model.EntityRefs
                );
                writer.Line();
                Offsets(
                    writer,
                    model.FullName,
                    "public static",
                    "__EcsBufferHandles",
                    model.BufferHandles
                );
                writer.Line();
                BufferOps(writer, "public static", "__EcsBufferOps", model.BufferHandles);
                foreach (var index in model.Indexes.Items)
                {
                    writer.Line();
                    IndexEmitter.Keyer(writer, model, index);
                }
            }
            if (model.Kind == DeclKind.Rows && model.KeyType is { } key)
            {
                writer.Line();
                writer.Line(
                    $"{key} global::Tralys.Ecs.IRow<{key}>.RowKey {{ readonly get => {model.KeyField}; set => {model.KeyField} = value; }}"
                );
            }
        }

        for (var i = scopes.Count - 1; i >= 0; i--)
            scopes[i].Dispose();
        if (!model.Indexes.Items.IsEmpty)
        {
            writer.Line();
            IndexEmitter.Accessors(writer, model);
        }
        if (
            model.Kind == DeclKind.Rows
            && model.KeyType is { } rowKey
            && model.AccessorVisibility.Length > 0
        )
        {
            writer.Line();
            RowsAccessors(writer, model, rowKey);
        }
        return writer.ToString();
    }

    static void RowsAccessors(CodeWriter writer, TypeModel model, string key)
    {
        var owner =
            string.Concat(model.Containers.Items.Select(c => c.Name)) + model.DeclarationName;
        var name = Symbols.RowsAccessor(model.DeclarationName);
        var arguments = $"<{key}, {model.FullName}>";
        using (writer.Block($"{model.AccessorVisibility} static class {owner}RowsAccess"))
        {
            writer.Line(
                $"public static global::Tralys.Ecs.Rows{arguments} {name}(this global::Tralys.Ecs.World world, global::Tralys.Ecs.Entity entity) => global::Tralys.Ecs.Generated.Plumbing.Rows{arguments}(world, entity);"
            );
            writer.Line(
                $"public static global::Tralys.Ecs.CommandRows{arguments} {name}(this global::Tralys.Ecs.Commands commands, global::Tralys.Ecs.Entity entity) => global::Tralys.Ecs.Generated.Plumbing.Rows{arguments}(commands, entity);"
            );
            writer.Line(
                $"public static global::Tralys.Ecs.Rows{arguments} {name}(this global::Tralys.Ecs.WorldEntity entity) => global::Tralys.Ecs.Generated.Plumbing.Rows{arguments}(entity);"
            );
        }
    }

    static string Interfaces(TypeModel model)
    {
        var list = new List<string>();
        switch (model.Kind)
        {
            case DeclKind.Component:
                list.Add(
                    (model.Traits & Traits.ReplaceOnly) != 0
                        ? "global::Tralys.Ecs.IReplaceOnly"
                        : "global::Tralys.Ecs.IMutableComponent"
                );
                if ((model.Traits & Traits.Enableable) != 0)
                    list.Add("global::Tralys.Ecs.IEnableable");
                if ((model.Traits & Traits.Singleton) != 0)
                    list.Add("global::Tralys.Ecs.ISingleton");
                break;
            case DeclKind.Tag:
                list.Add("global::Tralys.Ecs.ITag");
                if ((model.Traits & Traits.Enableable) != 0)
                    list.Add("global::Tralys.Ecs.IEnableable");
                if ((model.Traits & Traits.Singleton) != 0)
                    list.Add("global::Tralys.Ecs.ISingleton");
                break;
            case DeclKind.Relation:
                list.Add("global::Tralys.Ecs.IRelation");
                break;
            case DeclKind.Rows:
                list.Add(
                    model.KeyType is null
                        ? "global::Tralys.Ecs.IRow"
                        : $"global::Tralys.Ecs.IRow<{model.KeyType}>"
                );
                break;
        }
        if ((model.Traits & Traits.Tracked) != 0)
            list.Add("global::Tralys.Ecs.ITracked");
        return string.Join(", ", list);
    }

    static void Prologue(CodeWriter writer, string fullName)
    {
        writer.Line($"{fullName} v = default;");
        writer.Line($"ref byte b = ref {Unsafe}.As<{fullName}, byte>(ref v);");
    }

    static string Offset(string type, string access) =>
        $"(int){Unsafe}.ByteOffset(ref b, ref {Unsafe}.As<{type}, byte>(ref {Unsafe}.AsRef(in {access})))";

    static void Fields(CodeWriter writer, TypeModel model)
    {
        writer.Line(Hidden);
        using (writer.Block("public static global::Tralys.Ecs.FieldDescriptor[] __EcsFields()"))
        {
            if (model.Fields.Items.IsEmpty)
            {
                writer.Line("return [];");
                return;
            }
            Prologue(writer, model.FullName);
            writer.Line("return");
            writer.Line("[");
            using (writer.Indented())
            {
                foreach (var field in model.Fields.Items)
                {
                    writer.Line(
                        $"new(\"{field.Name}\", {Offset(field.Type, field.Access)}, global::System.Runtime.CompilerServices.Unsafe.SizeOf<{field.Type}>(), \"{field.Type}\", "
                            + $"(global::Tralys.Ecs.CapturePolicy){field.Capture}, {Passthrough(field.Passthrough)}),"
                    );
                }
            }
            writer.Line("];");
        }
    }

    static void Offsets(
        CodeWriter writer,
        string fullName,
        string modifiers,
        string name,
        EquatableArray<RefModel> refs
    )
    {
        writer.Line(Hidden);
        using (writer.Block($"{modifiers} int[] {name}()"))
        {
            if (refs.Items.IsEmpty)
            {
                writer.Line("return [];");
                return;
            }
            Prologue(writer, fullName);
            writer.Line(
                $"var offsets = new global::System.Collections.Generic.List<int>({refs.Items.Length});"
            );
            foreach (var slot in refs.Items)
            {
                var add = $"offsets.Add({Offset(slot.Type, slot.Access)});";
                writer.Line(slot.Guard is null ? add : $"if ({slot.Guard}) {add}");
            }
            writer.Line("return offsets.ToArray();");
        }
    }

    static void BufferOps(
        CodeWriter writer,
        string modifiers,
        string name,
        EquatableArray<RefModel> handles
    )
    {
        writer.Line(Hidden);
        writer.Line(
            $"{modifiers} global::Tralys.Ecs.Generated.BufferOps[] {name}() => ["
                + string.Join(
                    ", ",
                    handles.Items.Select(h =>
                        $"global::Tralys.Ecs.Generated.BufferOps.For<{h.Type}>()"
                    )
                )
                + "];"
        );
    }

    public static string Passthrough(EquatableArray<PassthroughModel> uses)
    {
        if (uses.Items.IsEmpty)
            return "[]";
        var parts = uses.Items.Select(use =>
            $"new global::Tralys.Ecs.PassthroughUse(\"{use.Attribute}\", new object?[] {{ {string.Join(", ", use.Arguments.Items)} }}, "
            + $"new string?[] {{ {string.Join(", ", use.Names.Items.Select(n => n.Length == 0 ? "null" : "\"" + n + "\""))} }})"
        );
        return "[" + string.Join(", ", parts) + "]";
    }

    public static string Module(
        string assembly,
        IReadOnlyList<TypeModel> types,
        IReadOnlyList<(InstanceModel Instance, TypeModel Definition)> instances,
        EquatableArray<string> referenced
    )
    {
        var writer = new CodeWriter();
        writer.Line(Header);
        var names = types
            .Select(t => t.DisplayName)
            .Concat(instances.Select(i => i.Instance.DisplayName));
        writer.Line(
            $"[assembly: global::Tralys.Ecs.Generated.ComponentModuleManifest(new string[] {{ {string.Join(", ", names.Select(n => "\"" + n + "\""))} }})]"
        );
        writer.Line();
        writer.Line($"namespace {Namespace(assembly)};");
        writer.Line();
        writer.Line(
            $"/// <summary>The components {assembly} declares. Pass <c>All</c> to <c>Registry.Build</c>.</summary>"
        );
        using (writer.Block("public static class EcsModule"))
        {
            var calls = new List<string>();
            var n = 0;
            foreach (var type in types)
                calls.Add($"D{n++}()");
            foreach (var instance in instances)
                calls.Add($"D{n++}()");
            writer.Line(
                $"public static readonly global::Tralys.Ecs.ComponentModule Module = new(\"{assembly}\", [{string.Join(", ", calls)}]);"
            );
            writer.Line();
            writer.Line(
                "/// <summary>This assembly's module and those of every assembly it references, for <c>Registry.Build(EcsModule.All)</c>.</summary>"
            );
            writer.Line(
                $"public static readonly global::Tralys.Ecs.ComponentModule[] All = [Module{string.Concat(referenced.Items.Select(r => $", .. global::{r}.EcsModule.All"))}];"
            );

            n = 0;
            foreach (var type in types)
            {
                writer.Line();
                Descriptor(
                    writer,
                    n++,
                    type.FullName,
                    type.DisplayName,
                    type.Version,
                    type,
                    type.Layout,
                    type.FullName
                );
            }
            foreach (var (instance, definition) in instances)
            {
                writer.Line();
                var at = n++;
                Descriptor(
                    writer,
                    at,
                    instance.FullName,
                    instance.DisplayName,
                    instance.Version,
                    definition,
                    instance.Layout,
                    instance.FullName,
                    $"I{at}"
                );
                writer.Line();
                Offsets(
                    writer,
                    instance.FullName,
                    "static",
                    $"I{at}EntityRefs",
                    instance.EntityRefs
                );
                writer.Line();
                Offsets(
                    writer,
                    instance.FullName,
                    "static",
                    $"I{at}BufferHandles",
                    instance.BufferHandles
                );
                writer.Line();
                BufferOps(writer, "static", $"I{at}BufferOps", instance.BufferHandles);
            }
        }
        return writer.ToString();
    }

    static void Descriptor(
        CodeWriter writer,
        int n,
        string fullName,
        string displayName,
        int version,
        TypeModel shape,
        ulong layout,
        string tableOwner,
        string? closedTables = null
    )
    {
        writer.Line($"static global::Tralys.Ecs.ComponentDescriptor D{n}() =>");
        writer.Line(
            $"    global::Tralys.Ecs.Generated.Plumbing.CreateDescriptor<{fullName}>(new global::Tralys.Ecs.Generated.ComponentInfo"
        );
        writer.Line("    {");
        using (writer.Indented())
        using (writer.Indented())
        {
            writer.Line($"SchemaVersion = {version},");
            writer.Line($"Name = \"{displayName}\",");
            writer.Line($"LayoutHash = {layout}UL,");
            writer.Line($"Kind = (global::Tralys.Ecs.DescriptorKind){(int)shape.Kind},");
            writer.Line($"Traits = (global::Tralys.Ecs.ComponentTraits){shape.Traits},");
            writer.Line($"Storage = (global::Tralys.Ecs.StorageKind){shape.Storage},");
            writer.Line(
                $"RelationTraits = (global::Tralys.Ecs.RelationTraits){shape.RelationTraits},"
            );
            writer.Line(
                $"OnTargetDestroyed = (global::Tralys.Ecs.TargetPolicy){shape.OnTargetDestroyed},"
            );
            writer.Line($"Categories = {shape.Categories}UL,");
            writer.Line(
                $"Aliases = [{string.Join(", ", shape.Aliases.Items.Select(a => "\"" + a + "\""))}],"
            );
            writer.Line(
                $"RequiresNames = [{string.Join(", ", shape.RequiresNames.Items.Select(r => "\"" + r + "\""))}],"
            );
            writer.Line(
                $"Indexes = [{string.Join(", ", shape.Indexes.Items.Select(i => IndexEmitter.Declaration(i, tableOwner)))}],"
            );
            writer.Line($"Passthrough = {Passthrough(shape.Passthrough)},");
            if (shape.KeyField is not null)
                writer.Line($"KeyField = \"{shape.KeyField}\",");
            if (shape.Kind != DeclKind.Tag)
            {
                writer.Line($"Fields = {tableOwner}.__EcsFields(),");
                if (closedTables is null)
                {
                    writer.Line($"EntityRefOffsets = {tableOwner}.__EcsEntityRefs(),");
                    writer.Line($"BufferHandleOffsets = {tableOwner}.__EcsBufferHandles(),");
                    writer.Line($"BufferOps = {tableOwner}.__EcsBufferOps(),");
                }
                else
                {
                    writer.Line($"EntityRefOffsets = {closedTables}EntityRefs(),");
                    writer.Line($"BufferHandleOffsets = {closedTables}BufferHandles(),");
                    writer.Line($"BufferOps = {closedTables}BufferOps(),");
                }
            }
            if (shape.Kind == DeclKind.Rows && shape.KeyType is { } key)
            {
                writer.Line(
                    $"RowFactory = global::Tralys.Ecs.Generated.RowStoreFactory.For<{key}, {fullName}>(),"
                );
            }
        }
        writer.Line("    });");
    }

    public static string Quote(string? text) => text is null ? "null" : "\"" + text + "\"";

    public static string Namespace(string assembly)
    {
        var segments = assembly
            .Split('.')
            .Select(segment =>
            {
                var text = new StringBuilder();
                foreach (var c in segment)
                    text.Append(char.IsLetterOrDigit(c) || c == '_' ? c : '_');
                if (text.Length == 0 || char.IsDigit(text[0]))
                    text.Insert(0, '_');
                return text.ToString();
            });
        return string.Join(".", segments);
    }
}
